# Provider-to-category routing: one provider can participate in multiple shared
# category ecosystems. Provider-owned folders hold provider-specific catalog/config;
# shared category folders hold reusable cross-provider capability interfaces.
PROVIDER_CATEGORY_ROUTES: dict[str, dict[str, str]] = {
    record["provider_id"]: {
        family: f"backend/api/global_ecosystem/global_api_ecosystem/global_{family.lower()}_api_ecosystem"
        for family in record["families"]
    }
    for record in PROVIDER_ECOSYSTEMS
}


def list_provider_category_routes(provider_id: str | None = None) -> dict[str, dict[str, str]]:
    """Return provider-to-shared-family paths; this is routing metadata, not a live API check."""
    routes = deepcopy(PROVIDER_CATEGORY_ROUTES)
    if provider_id is None:
        return routes
    key = provider_id.strip().casefold()
    return {key: routes[key]} if key in routes else {}


AI_API_PROVIDER_IDS = {
    "openai", "google", "microsoft", "aws", "nsfwinfra", "anthropic", "meta",
    "nvidia", "huggingface", "deepseek", "mistral", "cohere", "oracle", "ibm",
}


def list_ecosystems() -> list[dict[str, Any]]:
    return deepcopy(list(GLOBAL_API_ECOSYSTEMS))


def list_provider_ecosystems(family: str | None = None) -> list[dict[str, Any]]:
    records = list(PROVIDER_ECOSYSTEMS)
    if family:
        key = family.strip().upper()
        records = [record for record in records if key in record["families"]]
    return deepcopy(records)


def get_provider_ecosystem(provider_id: str) -> dict[str, Any] | None:
    key = provider_id.strip().casefold()
    for record in PROVIDER_ECOSYSTEMS:
        if record["provider_id"] == key:
            return deepcopy(record)
    return None


def list_ai_api_provider_ecosystems() -> list[dict[str, Any]]:
    return [
        record for record in list_provider_ecosystems("AI")
        if record["provider_id"] in AI_API_PROVIDER_IDS
    ]
